-- Moonsault / Yale BSC5 (J2000), curated data import; 9096 HR stars.
-- Derived from https://github.com/brettonw/YaleBrightStarCatalog/blob/master/bsc5-short.json
-- Source Git blob: 78768ccb6b7fe308e8ddfed8003a5bc60a4c3cc4
-- Missing HR numbers (14 original catalogue historical non-stars) are intentional.
-- J2000 means source equinox and epoch; proper motion not present in SHORT source.
CREATE TABLE IF NOT EXISTS moonsault_bsc5 (
 hr INTEGER PRIMARY KEY,
 ra_j2000_deg DECIMAL(12,8) NOT NULL,
 dec_j2000_deg DECIMAL(12,8) NOT NULL,
 visual_mag DECIMAL(5,2) NOT NULL,
 proper_name VARCHAR(100),
 bayer VARCHAR(24),
 constellation VARCHAR(3),
 flamsteed INTEGER,
 approx_kelvin INTEGER
);
CREATE INDEX IF NOT EXISTS moonsault_bsc5_radec ON moonsault_bsc5 (ra_j2000_deg,dec_j2000_deg);
-- One-time, all-or-nothing SQLite load. Do NOT run against a populated copy.
BEGIN IMMEDIATE;
COMMIT;
